<script setup lang="ts">
import {
  clearFeedbackEntry,
  feedbackKeyFor,
  loadFeedback,
  setFeedbackEntry,
  storeFeedback,
  type FeedbackVerdict,
  type ProposalFeedbackMap,
} from "../utils/proposal-feedback";

const props = defineProps<{ proposalId?: string; proposalTitle: string }>();

const storageKeyFor = (id: string | undefined) => feedbackKeyFor(id);
const entries = ref<ProposalFeedbackMap>({});
const reasonDraft = ref("");
const storageProblem = ref<"malformed" | "unavailable" | "">("");
const saveProblem = ref(false);

const feedbackId = computed(() => storageKeyFor(props.proposalId));
const saved = computed(() => (feedbackId.value ? entries.value[feedbackId.value] : undefined));
const verdict = computed<FeedbackVerdict | undefined>(() => saved.value?.verdict);

watch(
  () => props.proposalId,
  () => {
    reasonDraft.value = saved.value?.reason ?? "";
    saveProblem.value = false;
  },
);

onMounted(() => {
  try {
    const loaded = loadFeedback(localStorage);
    entries.value = loaded.entries;
    reasonDraft.value = saved.value?.reason ?? "";
    if (loaded.unavailable) storageProblem.value = "unavailable";
    else if (loaded.malformed) storageProblem.value = "malformed";
  } catch {
    storageProblem.value = "unavailable";
  }
});

function persist(next: ProposalFeedbackMap) {
  try {
    const result = storeFeedback(localStorage, next);
    saveProblem.value = result.unavailable;
    if (!result.unavailable) entries.value = next;
  } catch {
    saveProblem.value = true;
  }
}

function choose(value: FeedbackVerdict) {
  const id = feedbackId.value;
  if (!id) return;
  persist(setFeedbackEntry(entries.value, id, { verdict: value, reason: reasonDraft.value }));
}

function saveReason() {
  const id = feedbackId.value;
  const current = saved.value;
  if (!id || !current) return;
  persist(setFeedbackEntry(entries.value, id, { verdict: current.verdict, reason: reasonDraft.value }));
}

function clear() {
  const id = feedbackId.value;
  if (!id) return;
  reasonDraft.value = "";
  persist(clearFeedbackEntry(entries.value, id));
}
</script>

